const helpers = this.helpers;
const userId = $("Buscar Usuario ID").item.json.userId;
const userMobile = $("Buscar Usuario ID").item.json.userMobile || "";
const ticketId = $("Criar Chamado GLPI").item.json.id;
if (!userId || !ticketId) return [$input.first()];
const token = $("Chamar Auth").item.json.access_token;
const headers = { "Authorization": "Bearer " + token, "Content-Type": "application/json" };

// 1) Adicionar requerente ao ticket
try {
  await helpers.httpRequest({
    method: "POST",
    url: "https://suporte.araraquara.sp.gov.br/api.php/v2/Assistance/Ticket/" + ticketId + "/TeamMember",
    headers,
    body: { type: "User", id: userId, role: "requester" }
  });
} catch(e) { /* ignora */ }

// 2) Atualizar celular do usuario SO se ele estiver vazio
const celularTrigger = $("Trigger").item.json.celular || $("Trigger").item.json.telefone || "";
if (celularTrigger && !userMobile) {
  try {
    await helpers.httpRequest({
      method: "PATCH",
      url: "https://suporte.araraquara.sp.gov.br/api.php/v2/Administration/User/" + userId,
      headers,
      body: { mobile: celularTrigger }
    });
  } catch(e) { /* ignora */ }
}

return [$input.first()];

