const helpers = this.helpers;
const token = $("Chamar Auth").item.json.access_token;
const d = $("Trigger").item.json;
const email = d.email_pessoal || d.email_unidade || d.email_institucional || "";
const login = d.nome_usuario || d.login_usuario_reset || d.login_usuario_reativar || d.login_usuario_desativar || d.login_usuario_transferir || "";
const nome  = d.nome_completo || d.nome_solicitante || "";

async function searchUser(filter, requireUnique) {
  try {
    const r = await helpers.httpRequest({
      method: "GET",
      url: `https://suporte.araraquara.sp.gov.br/api.php/v2/Administration/User?filter=${encodeURIComponent(filter)}`,
      headers: { "Authorization": "Bearer " + token }
    });
    const users = Array.isArray(r) ? r : (r?.data ? r.data : []);
    if (users.length === 0) return null;
    if (requireUnique && users.length > 1) return null;
    return users[0];
  } catch(e) { return null; }
}

let user = null;
if (email) user = await searchUser(`emails.email==${email}`, false);
if (!user && login) user = await searchUser(`username==${login}`, false);
if (!user && nome) {
  const first = nome.trim().split(/\s+/)[0];
  if (first) user = await searchUser(`firstname==${first}`, true);
}

return [{ json: {
  userId:     user?.id || 0,
  userMobile: user?.mobile || "",
  email, login, nome
} }];
